"""Add completed two-direction scalar C replay and bounded reverse RTL evidence."""
from pathlib import Path
import json,hashlib,time,os
R=Path(__file__).resolve().parents[1]
def sha(p):
 h=hashlib.sha256()
 with Path(p).open('rb') as f:
  for b in iter(lambda:f.read(8*1024*1024),b''):h.update(b)
 return h.hexdigest()
def main():
 old=R/'work/current_research_claim_matrix_v23_20261021/matrix.json';m=json.loads(old.read_text());drift=[n for n,h in m['source_sha256'].items() if not (R/n).exists() or sha(R/n)!=h];assert not drift,drift
 o=R/'work/current_research_claim_matrix_v24_20261021';o.mkdir();p=R/'experiments/research_plan.json';raw=p.read_bytes();plan=json.loads(raw);(o/'plan_snapshot.json').write_bytes(raw)
 specs=[('R_SCALAR_BOTH_FULL',['G2','G6'],'All39536original complete-parent trace jobs match actual forward and reverse scalar HLS-source C entrypoints,original oracle and19768portal decisions',['work/resident_both_word_trace_review_queue_20261021/audit.json'], 'One original seed6parent workload,19768jobs each direction. Preserves ordered journals,labels,work,downstream and portal assertions;8fixture jobs and2corrupt-trace controls precede full run. Not representative multi-case RTL,full hardware authority,native quality repair,physical throughput or speedup.1092.339601691s includes IO/setup/independent CPU oracle checking and is not accelerator timing.'),('H_REVERSE_WORD_FIXTURE',['G6'],'Explicit scalar reverse interface passes9Verilog calls and4output-bundle byte comparisons;2000random C cases match original aggregate implementation',['work/resident_tail_word_HLS_v2_20261021/independent_RTL_review.json','work/resident_tail_word_random_C_20261021/review.json'],'RTL covers one valid2nodezero-costalias task plus8rejects.4607cycles valid fixture;reported18608total includes rejected calls. Random2000are C-only evidence here;separate2000RTLrun is still pending. HLS LUT69183,FF41256,DSP160,estimated2.433ns are not routed timing or performance. Original pre-RTL aggregate-pointer failure retained.'),('L_AUTHOR_THESIS',['G8'],'Selected author thesis chapter3.3.1 provides bounded primary RWRoute methodology review',['work/rwroute_author_thesis_primary_review_20261021/review.json'],'Public206pageauthor thesis;onlyPDFpages106–109/printed78–81selected. Connectionboxes,sharing,congestion anddistanceheuristics are prior comparison axes. Not journal full-text review or exhaustive novelty proof;no performance metric is imported as a comparable DieRoute speedup.')]
 ids={c['id'] for c in m['claims']}
 for ident,gates,claim,ev,limits in specs:
  assert ident not in ids;m['claims'].append(dict(id=ident,gates=gates,claim=claim,evidence=ev,limits=limits,status='supported_in_declared_scope'))
  for name in ev:m['source_sha256'][name]=sha(R/name)
 gates=[{k:g[k] for k in ['id','requirement','status']} for g in plan['gates']];assert len(gates)==8 and all(g['status']!='complete' for g in gates)
 m.update(schema='dieroute.claim_matrix.v24',recorded_ns=time.time_ns(),gates=gates,predecessor={'path':str(old.relative_to(R)),'sha256':sha(old)},scope='Original8gates open. Add complete one-input both-scalar-source C trace replay,finite reverse RTL and selected author-thesis methodology;no new native cohort outcome,representative RTL or board result.',research_complete=False,board_result=False)
 for f in [old,Path(__file__),o/'plan_snapshot.json']:m['source_sha256'][str(f.relative_to(R))]=sha(f)
 target=o/'matrix.json';target.write_text(json.dumps(m,ensure_ascii=False,indent=2)+'\n');plan['current_claim_matrix']={'path':str(target.relative_to(R)),'sha256':sha(target),'status':m['status'],'research_complete':False}
 critical=R/'experiments/critical_path_20261020.md';before=critical.read_bytes();(o/'critical_path_before.md').write_bytes(before);s=before.decode().replace('v23 matrix has43scoped claims and228direct references',f'v24 matrix has{len(m["claims"])}scoped claims and{len(m["source_sha256"])}direct references').replace('work/current_research_claim_matrix_v23_20261021/matrix.json','work/current_research_claim_matrix_v24_20261021/matrix.json');s+='\nTerminal scalar operator update: `work/resident_both_word_trace_review_queue_20261021/audit.json` verifies all39536original seed6jobs and19768portal decisions with actual forward/reverse scalar HLS-source C. Reverse finiteRTL independently passes9calls (one validalias+8rejects), not complete real workloads.2000random Ccases pass;their separateRTLrun remains pending. No representative throughput,physical execution or gate closure.\n';assert critical.read_bytes()==before;critical.write_text(s);plan['completion_critical_path']['sha256']=sha(critical)
 assert p.read_bytes()==raw;t=p.with_name('.research_plan_matrix24.tmp');t.write_text(json.dumps(plan,indent=2,ensure_ascii=False)+'\n');os.replace(t,p)
 review=dict(status='new_terminal_scoped_evidence_reconciled_all8gates_open',claims=len(m['claims']),direct_sources=len(m['source_sha256']),predecessor_source_drift=drift,open_gates=8,matrix_sha256=sha(target),research_complete=False);(o/'review.json').write_text(json.dumps(review,indent=2)+'\n');print(json.dumps(review))
